#!/usr/bin/env node
// Generates docs/architecture/inventory.md by walking the filesystem and
// regex-scraping `export` lines. No TypeScript AST dependency — this only
// needs to answer "does X exist and what's it called?", and a regex over
// export lines is accurate enough for that.
//
// This file is generated, like src/integrations/supabase/types.ts — never
// hand-edit it. Two devs regenerating it at once produces a one-file
// conflict; resolve with `git checkout --ours docs/architecture/inventory.md
// && npm run docs:arch`, same recipe the Supabase types file already uses.
//
// Run: npm run docs:arch          (writes the file)
//      npm run docs:arch -- --check   (exits non-zero if the file is stale)

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = process.cwd();
const OUT = path.join(root, "docs/architecture/inventory.md");
const CHECK = process.argv.includes("--check");

const read = (p) => {
  try {
    return readFileSync(p, "utf8");
  } catch {
    return null;
  }
};

function walk(dir, exts) {
  const out = [];
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full, exts));
    else if (exts.some((e) => entry.name.endsWith(e))) out.push(full);
  }
  return out;
}

// The framework/app split means a domain (routes, services, hooks, types, constants) can have
// files on both sides of the boundary — an app's own plus the framework's, now under platform/.
// Every inventory section for one of these domains has to scan both roots or it silently goes
// blind to half the codebase the moment anything moves. Order: app files first, then framework's.
function walkBoth(appDir, frameworkDir, exts) {
  return [
    ...walk(path.join(root, appDir), exts),
    ...walk(path.join(root, frameworkDir), exts),
  ];
}

const rel = (p) => path.relative(root, p).split(path.sep).join("/");

const isFrameworkPath = (p) => rel(p).startsWith("platform/");

function exportNames(content, pattern) {
  return [...content.matchAll(pattern)].map((m) => m[1]);
}

// Renders one domain in two labelled halves — the portal's own files first, the framework's after.
//
// WHY: this file is what CLAUDE.md points agents at to answer "does X exist and what's it called?".
// In a flat list a portal's 3 services sit below the framework's 5, and its own components below
// ~54 framework ones, so the signal an agent actually needs — what does THIS app have — is the
// hardest thing to find. Splitting costs nothing and puts it first.
//
// The framework half stays in the file rather than being dropped: an agent still needs to know a
// component exists before it can reuse it instead of rebuilding it.
function pushSplit(files, render) {
  const app = files.filter((f) => !isFrameworkPath(f));
  const framework = files.filter(isFrameworkPath);

  push("**This app**");
  push();
  if (app.length === 0) {
    push("_(none yet)_");
  } else {
    for (const f of app) push(render(f));
  }
  push();

  if (framework.length) {
    push("**Framework (reference — read-only, `@framework/*`)**");
    push();
    for (const f of framework) push(render(f));
    push();
  }
}

const lines = [];
const push = (s = "") => lines.push(s);

push("<!-- GENERATED by `npm run docs:arch` — do not hand-edit. -->");
push(
  "<!-- Two devs regenerating this at once = a one-file conflict.       -->",
);
push(
  "<!-- Resolve with: git checkout --ours docs/architecture/inventory.md -->",
);
push(
  "<!--               && npm run docs:arch                              -->",
);
push();
push("# Architecture inventory (generated)");
push();
push("Answers \"does X exist and what's it called?\". For *why* it's built");
push("this way, see the hand-written docs indexed below.");
push();
push(
  "Each section lists **this app's** own files first, then the **framework's**",
);
push(
  "as reference. Framework files are read-only in a portal and imported via",
);
push('`@framework/*` — see `CLAUDE.md`\'s "extend, never edit" section.');
push();

// --- Routes ---
// A table rather than the two-part split the list sections use — an Owner column keeps every route
// in one place you can scan by path, which is how you actually look a route up.
push("## Routes");
push();
push("| Path | Owner | Access | Required role | Layout | Module |");
push("| --- | --- | --- | --- | --- | --- |");
const routeFiles = walkBoth(
  "src/routes/modules",
  "platform/src/routes/modules",
  [".routes.tsx"],
);
for (const file of routeFiles) {
  const content = read(file) ?? "";
  const owner = isFrameworkPath(file) ? "framework" : "**app**";
  const objectPattern = /\{[^{}]*path:\s*"([^"]+)"[^{}]*\}/g;
  for (const match of content.matchAll(objectPattern)) {
    const block = match[0];
    const routePath = match[1];
    const access = block.match(/access:\s*"([^"]+)"/)?.[1] ?? "authenticated";
    const role = block.match(/requiredRole:\s*([^\n,}]+)/)?.[1]?.trim() ?? "";
    const layout = block.match(/layout:\s*"([^"]+)"/)?.[1] ?? "default";
    push(
      `| \`${routePath}\` | ${owner} | ${access} | ${role || "—"} | ${layout} | ${rel(file)} |`,
    );
  }
}
push();

// --- Services ---
const withExports = (file) => {
  const content = read(file) ?? "";
  const names = [
    ...exportNames(content, /export (?:async )?function (\w+)/g),
    ...exportNames(content, /export const (\w+)\s*=/g),
  ];
  return `- \`${rel(file)}\` — ${names.map((n) => `\`${n}\``).join(", ") || "(no exports found)"}`;
};

push("## Services");
push();
pushSplit(
  walkBoth("src/services", "platform/src/services", [".ts"]),
  withExports,
);

// --- Hooks ---
push("## Hooks");
push();
pushSplit(
  walkBoth("src/hooks", "platform/src/hooks", [".ts", ".tsx"]),
  withExports,
);

// --- UI components ---
// Framework-owned only — no app-side src/components/ui/ equivalent exists.
push("## UI components (`platform/src/components/ui/`)");
push();
const uiFiles = walk(path.join(root, "platform/src/components/ui"), [
  ".ts",
  ".tsx",
]);
for (const file of uiFiles) {
  push(`- \`${rel(file)}\``);
}
push();

// --- Page templates ---
// One entry per shell. A template is defined by its holes and its arrangement
// props, so those are the columns — a template is never named after a job, and
// nothing here should read like one ("Single card", not "Form page").
// Framework-owned only — templates have no app-side equivalent path.
push("## Page templates (`platform/src/templates/`)");
push();
push(
  "| Template | Shell | Holes | Props (first value is the default) | Preview |",
);
push("| --- | --- | --- | --- | --- |");
const registry =
  read(path.join(root, "platform/src/templates/registry.ts")) ?? "";
const entryPattern = /\{\s*id:\s*"([^"]+)"[\s\S]*?previewRoute:\s*"([^"]+)"/g;
for (const match of registry.matchAll(entryPattern)) {
  const block = match[0];
  const id = match[1];
  const preview = match[2];
  const shell = block.match(/shell:\s*"([^"]+)"/)?.[1] ?? "";
  const holes = block.match(/holes:\s*\[([^\]]*)\]/)?.[1] ?? "";
  // `options` holds string arrays, so it has `[` inside but never a nested `{`.
  const options = block.match(/options:\s*\{([^{}]*)\}/)?.[1] ?? "";
  const holeList = [...holes.matchAll(/"([^"]+)"/g)]
    .map((m) => m[1])
    .join(", ");
  const optionList = [...options.matchAll(/(\w+):\s*\[([^\]]*)\]/g)]
    .map(
      ([, prop, values]) =>
        `${prop}: ${[...values.matchAll(/"([^"]+)"/g)].map((m) => m[1]).join(" \\| ")}`,
    )
    .join("<br>");
  push(
    `| \`${id}\` | \`${shell.split("/").pop()}\` | ${holeList || "—"} | ${optionList || "—"} | \`${preview}\` |`,
  );
}
push();

// --- Pages ---
// Three roots: the app's own pages, the framework's system pages (Login/NotFound), and the
// framework's sample gallery — all genuinely "pages" for this listing's purpose.
push("## Pages");
push();
pushSplit(
  [
    ...walk(path.join(root, "src/pages"), [".tsx"]),
    ...walk(path.join(root, "platform/src/pages"), [".tsx"]),
    ...walk(path.join(root, "platform/src/samples"), [".tsx"]),
  ],
  (file) => `- \`${rel(file)}\``,
);

// --- Design tokens ---
// The legal visual vocabulary, scraped from the framework CSS's @theme inline
// block so it cannot drift from the actual tokens. This is the "what am I
// allowed to use?" answer that prevents a violation, paired with the
// local/no-raw-colors and local/no-off-scale-spacing ESLint rules that catch one.
//
// Resolved by first-existing candidate: the block moved out of src/index.css in
// the framework/app split (values stayed app-owned in src/theme.css) and moves
// again into platform/ in phase 2. Hardcoding one path means a move silently
// generates an empty token list, which reads as "no tokens exist" rather than
// as a broken script.
//
// Deliberately a flat sorted list rather than hand-curated semantic groupings —
// a grouping map here would silently go stale the first time a token is added
// without updating it.
push("## Design tokens (framework CSS `@theme inline`)");
push();
push(
  "The only legal colors. Prefix with `bg-` / `text-` / `border-` / `ring-`",
);
push(
  "(e.g. `--color-muted-foreground` -> `text-muted-foreground`). A `-foreground`",
);
push(
  "token is the readable color to place *on* its same-named surface. Opacity",
);
push(
  "modifiers are fine (`bg-destructive/10`). Never a raw hex, a Tailwind palette",
);
push(
  "class (`bg-blue-500`), or bare `bg-white`/`text-black` — `npm run lint` errors.",
);
push();
const THEME_CSS_CANDIDATES = [
  "platform/src/styles/framework.css",
  "src/styles/framework.css",
  "src/index.css",
];
const themeBlock = (() => {
  for (const candidate of THEME_CSS_CANDIDATES) {
    const css = read(path.join(root, candidate));
    if (!css) continue;
    const start = css.indexOf("@theme inline {");
    if (start !== -1) return css.slice(start, css.indexOf("\n}", start));
  }
  return "";
})();
const colorTokens = [
  ...new Set(
    [...themeBlock.matchAll(/--color-([a-z0-9-]+)\s*:/g)].map((m) => m[1]),
  ),
].sort();
if (colorTokens.length === 0) {
  push("_(none found — has the `@theme inline` block moved?)_");
} else {
  for (const token of colorTokens) push(`- \`${token}\``);
}
push();
push("### Spacing scale");
push();
push("4px base unit — only these steps (DESIGN.md §5):");
push();
push("| Step | `1` | `2` | `3` | `4` | `6` | `8` | `12` | `16` |");
push("| --- | --- | --- | --- | --- | --- | --- | --- | --- |");
push("| px | 4 | 8 | 12 | 16 | 24 | 32 | 48 | 64 |");
push();
push(
  "Arbitrary values are allowed only when they land on the scale (`max-h-[300px]` is",
);
push(
  "fine, `mt-[7px]` errors). For a token-driven length use Tailwind v4's CSS-var",
);
push("shorthand — `max-w-(--container-max)`, not `max-w-[1280px]`.");
push();

// --- Type domains ---
push("## Type domains (`src/types/`, `platform/src/types/`)");
push();
pushSplit(
  walkBoth("src/types", "platform/src/types", [".ts"]).filter(
    (f) => !f.endsWith("index.ts"),
  ),
  (file) => {
    const names = exportNames(read(file) ?? "", /export type (\w+)/g);
    return `- \`${rel(file)}\` — ${names.map((n) => `\`${n}\``).join(", ") || "(no exports found)"}`;
  },
);

// --- Constant groups ---
push(
  "## Constant groups (`src/lib/constants/`, `platform/src/lib/constants/`)",
);
push();
pushSplit(
  walkBoth("src/lib/constants", "platform/src/lib/constants", [".ts"]).filter(
    (f) => !f.endsWith("index.ts"),
  ),
  (file) => {
    const names = exportNames(read(file) ?? "", /export const (\w+)/g);
    return `- \`${rel(file)}\` — ${names.map((n) => `\`${n}\``).join(", ") || "(no exports found)"}`;
  },
);
push();

// --- Doc index (hand-written docs, with their first blurb line) ---
push("## Hand-written docs");
push();
for (const sub of ["docs/architecture", "docs/features"]) {
  const dir = path.join(root, sub);
  const files = walk(dir, [".md"]).filter((f) => !f.endsWith("inventory.md"));
  for (const file of files) {
    const content = read(file) ?? "";
    const body = content.split("\n").slice(1); // skip the H1 title
    const blurb = body.find((l) => l.trim().length > 0)?.trim() ?? "";
    push(`- \`${rel(file)}\` — ${blurb}`);
  }
}
push();

const generated = lines.join("\n") + "\n";

if (CHECK) {
  const existing = read(OUT);
  if (existing !== generated) {
    console.error(
      "docs/architecture/inventory.md is stale — run `npm run docs:arch` and commit the result.",
    );
    process.exit(1);
  }
  console.log("docs/architecture/inventory.md is up to date");
  process.exit(0);
}

writeFileSync(OUT, generated);
console.log(`Wrote ${rel(OUT)}`);
